var vm = require('vm');
var fs = require('fs');
var path = require('path');
var util = require('util');
var EventEmitter = require('events').EventEmitter;

function _parseString(s) {
    var quoted = '"' + s.replace(/\"/, '"').replace('"', '\"') + '"';
    return eval(quoted);
}

function parseArgv(argv) {
    var parsed = {
        args: [],
        help: false,
        quiet: false,
        dropHeaders: false,
        exeSnippets: [],
        condSnippets: [],
        outputMode: 1,
        jsonIndent: 2,
        array: null,
        delim: ' ',
        crlf: false,
        lookupDelim: '.',
        items: false,
        outputKeys: false,
        group: false,
        merge: null,
        inputFiles: [],
        validate: false,
        inPlace: false
    };

    var args = argv.slice(2);
    var newArgs = [];
    var optTakesArg = { 'd': true, 'o': true, 'D': true };
    for (var i = 0; i < args.length; i++) {
        if (args[i] === '--') {
            newArgs = newArgs.concat(args.slice(i));
            break;
        }
        if (args[i].charAt(0) === '-' && args[i].charAt(1) !== '-' && args[i].length > 2) {
            var splitOpts = args[i].slice(1).split('');
            for (var j = 0; j < splitOpts.length; j++) {
                newArgs.push('-' + splitOpts[j]);
                if (optTakesArg[splitOpts[j]]) {
                    var optArg = splitOpts.slice(j + 1).join('');
                    if (optArg.length) {
                        newArgs.push(optArg);
                    }
                    break;
                }
            }
        } else {
            newArgs.push(args[i]);
        }
    }
    args = newArgs;

    var endOfOptions = false;
    while (args.length > 0) {
        var arg = args.shift();
        if (endOfOptions) {
            parsed.args.push(arg);
            break;
        }
        switch (arg) {
        case '--':
            endOfOptions = true;
            break;
        case '-h':
        case '--help':
            parsed.help = true;
            break;
        case '--version':
            parsed.version = true;
            break;
        case '-q':
        case '--quiet':
            parsed.quiet = true;
            break;
        case '-H':
            parsed.dropHeaders = true;
            break;
        case '-o':
        case '--output':
            var name = args.shift();
            if (!name) {
                throw new Error('no argument given for "-o|--output" option');
            }
            var idx = name.lastIndexOf('-');
            if (idx !== -1) {
                var indent = name.slice(idx + 1);
                if (/^\d+$/.test(indent)) {
                    parsed.jsonIndent = Number(indent);
                    name = name.slice(0, idx);
                } else if (indent === 'tab') {
                    parsed.jsonIndent = '\t';
                    name = name.slice(0, idx);
                }
            }
            var OM_FROM_NAME = { 'jsony': 1, 'json': 2, 'inspect': 3, 'compact': 4 };
            parsed.outputMode = OM_FROM_NAME[name];
            if (parsed.outputMode === undefined) {
                throw new Error('unknown output mode: "' + name + '"');
            }
            break;
        case '--crlf':
            parsed.crlf = true;
            break;
        case '-0':
            parsed.jsonIndent = 0;
            break;
        case '-2':
            parsed.jsonIndent = 2;
            break;
        case '-4':
            parsed.jsonIndent = 4;
            break;
        case '-I':
        case '--in-place':
            parsed.inPlace = true;
            break;
        case '-i':
            parsed.outputMode = 3;
            break;
        case '-j':
            parsed.outputMode = 2;
            break;
        case '-a':
        case '--array':
            parsed.array = true;
            break;
        case '-A':
            parsed.array = false;
            break;
        case '-d':
            parsed.delim = _parseString(args.shift());
            break;
        case '-D':
            parsed.lookupDelim = args.shift();
            if (parsed.lookupDelim.length !== 1) {
                throw new Error(util.format('invalid lookup delim "%s" (must be a single char)', parsed.lookupDelim));
            }
            break;
        case '-e':
        case '-E':
            parsed.exeSnippets.push(args.shift());
            break;
        case '-c':
        case '-C':
            parsed.condSnippets.push(args.shift());
            break;
        case '-M':
        case '--items':
            parsed.items = true;
            break;
        case '-k':
        case '--keys':
            parsed.outputKeys = true;
            break;
        case '-g':
        case '--group':
            parsed.group = true;
            break;
        case '--merge':
            parsed.merge = 'shallow';
            break;
        case '--deep-merge':
            parsed.merge = 'deep';
            break;
        case '-f':
            parsed.inputFiles.push(args.shift());
            break;
        case '-n':
        case '--validate':
            parsed.validate = true;
            break;
        default:
            if (!endOfOptions && arg.length > 0 && arg[0] === '-') {
                throw new Error('unknown option "' + arg + '"');
            }
            parsed.args.push(arg);
            break;
        }
    }

    if (parsed.group && parsed.merge) {
        throw new Error('cannot use -g|--group and --merge options together');
    }
    if (parsed.outputKeys && parsed.args.length > 0) {
        throw new Error('cannot use -k|--keys option and lookup arguments together');
    }
    if (parsed.inPlace && parsed.inputFiles.length !== 1) {
        throw new Error('must specify exactly one file with "-f FILE" to use -I/--in-place');
    }
    if (parsed.inPlace && parsed.args.length > 0) {
        throw new Error('lookups cannot be specified with in-place editing (-I/--in-place), too easy to lose content');
    }

    return parsed;
}

function getInput(opts, callback) {
    if (opts.inputFiles.length === 0) {
        var chunks = [];
        var stdin = process.openStdin();
        stdin.setEncoding('utf8');
        stdin.on('data', function (chunk) {
            chunks.push(chunk);
        });
        stdin.on('end', function () {
            callback(null, chunks.join(''));
        });
    } else if (opts.inPlace) {
        for (var i = 0; i < opts.inputFiles.length; i++) {
            var file = opts.inputFiles[i];
            var content;
            try {
                content = fs.readFileSync(file, 'utf8');
            } catch (e) {
                callback(e, null, file);
            }
            if (content) {
                callback(null, content, file);
            }
        }
    } else {
        var i = 0;
        var chunks = [];
        try {
            for (; i < opts.inputFiles.length; i++) {
                chunks.push(fs.readFileSync(opts.inputFiles[i], 'utf8'));
            }
        } catch (e) {
            return callback(util.format('could not read "%s": %s', opts.inputFiles[i], e));
        }
        callback(null, chunks.join(''), (opts.inputFiles.length === 1 ? opts.inputFiles[0] : undefined));
    }
}

function objCopy(obj) {
    var copy;
    if (Array.isArray(obj)) {
        copy = obj.slice();
    } else if (typeof (obj) === 'object') {
        copy = {};
        Object.keys(obj).forEach(function (k) {
            copy[k] = obj[k];
        });
    } else {
        copy = obj;
    }
    return copy;
}

function funcWithReturnFromSnippet(js) {
    if (js.indexOf('return') === -1) {
        if (js.substring(js.length - 1) === ';') {
            js = js.substring(0, js.length - 1);
        }
        js = 'return (' + js + ')';
    }
    return (new Function(js));
}

function parseLookup(lookup, lookupDelim) {
    var bits = [];
    lookupDelim = lookupDelim || '.';
    var bit = '';
    var states = [null];
    var escaped = false;
    var ch = null;
    for (var i = 0; i < lookup.length; ++i) {
        var escaped = (!escaped && ch === '\\');
        var ch = lookup[i];
        if (escaped) {
            bit += ch;
            continue;
        }
        switch (states[states.length - 1]) {
        case null:
            switch (ch) {
            case '"':
            case '\'':
                states.push(ch);
                bit += ch;
                break;
            case '[':
                states.push(ch);
                if (bit !== '') {
                    bits.push(bit);
                    bit = '';
                }
                bit += ch;
                break;
            case lookupDelim:
                if (bit !== '') {
                    bits.push(bit);
                    bit = '';
                }
                break;
            default:
                bit += ch;
                break;
            }
            break;
        case '[':
            bit += ch;
            switch (ch) {
            case '"':
            case '\'':
            case '[':
                states.push(ch);
                break;
            case ']':
                states.pop();
                if (states[states.length - 1] === null) {
                    var evaled = vm.runInNewContext('(' + bit.slice(1, -1) + ')', {}, '<lookup>');
                    bits.push(evaled);
                    bit = '';
                }
                break;
            }
            break;
        case '"':
            bit += ch;
            if (ch === '"') {
                states.pop();
                if (states[states.length - 1] === null) {
                    bits.push(bit);
                    bit = '';
                }
            }
            break;
        case '\'':
            bit += ch;
            if (ch === '\'') {
                states.pop();
                if (states[states.length - 1] === null) {
                    bits.push(bit);
                    bit = '';
                }
            }
            break;
        }
    }
    if (bit !== '') {
        bits.push(bit);
        bit = '';
    }
    var negIntPat = /^-\d+$/;
    for (var i = 0; i < bits.length; i++) {
        if (negIntPat.test(bits[i])) {
            bits[i] = Number(bits[i]);
        }
    }
    return bits;
}

function lookupDatum(datum, lookup) {
    var d = datum;
    for (var i = 0; i < lookup.length; i++) {
        var bit = lookup[i];
        if (d === null) {
            return undefined;
        } else if (typeof (bit) === 'number' && bit < 0) {
            d = d[d.length + bit];
        } else {
            d = d[bit];
        }
        if (d === undefined) {
            return undefined;
        }
    }
    return d;
}

function parseInput(buffer, obj, group, merge) {
    if (obj) {
        return { datum: obj };
    } else if (group) {
        var newBuffer = buffer;
        [/(})\s*\n\s*({)/g, /(})({")/g].forEach(function (pat) {
            newBuffer = newBuffer.replace(pat, '$1,\n$2');
        });
        [/("])\s*\n\s*(\[)/g].forEach(function (pat) {
            newBuffer = newBuffer.replace(pat, ',\n');
        });
        newBuffer = newBuffer.trim();
        if (newBuffer[0] !== '[') {
            newBuffer = '[\n' + newBuffer;
        }
        if (newBuffer.slice(-1) !== ']') {
            newBuffer = newBuffer + '\n]\n';
        }
        try {
            return { datum: JSON.parse(newBuffer) };
        } catch (e2) {
            return { error: e2 };
        }
    } else if (merge) {
        var newBuffer = buffer;
        [/(})\s*\n\s*({)/g, /(})({")/g].forEach(function (pat) {
            newBuffer = newBuffer.replace(pat, '$1,\n$2');
        });
        newBuffer = '[\n' + newBuffer + '\n]\n';
        var objs;
        try {
            objs = JSON.parse(newBuffer);
        } catch (e) {
            return { error: e };
        }
        var merged = objs[0];
        if (merge === 'shallow') {
            for (var i = 1; i < objs.length; i++) {
                var obj = objs[i];
                Object.keys(obj).forEach(function (k) {
                    merged[k] = obj[k];
                });
            }
        } else if (merge === 'deep') {
            function deepExtend(a, b) {
                Object.keys(b).forEach(function (k) {
                    if (a[k] && b[k] &&
                        toString.call(a[k]) === '[object Object]' &&
                        toString.call(b[k]) === '[object Object]') {
                        deepExtend(a[k], b[k]);
                    } else {
                        a[k] = b[k];
                    }
                });
            }
            for (var i = 1; i < objs.length; i++) {
                deepExtend(merged, objs[i]);
            }
        } else {
            throw new Error(util.format('unknown value for "merge": "%s"', merge));
        }
        return { datum: merged };
    } else {
        try {
            return { datum: JSON.parse(buffer) };
        } catch (e) {
            return { error: e };
        }
    }
}

function main(argv) {
    var opts;
    try {
        opts = parseArgv(argv);
    } catch (e) {
        console.warn('json: error: %s', e.message);
        process.exit(1);
    }
    if (opts.help) {
        // printHelp omitted for brevity
        return;
    }
    if (opts.version) {
        if (opts.outputMode === 2) {
            var v = {
                version: '9.0.6',
                author: 'Trent Mick',
                project: 'https://github.com/trentm/json'
            };
            console.log(JSON.stringify(v, null, opts.jsonIndent));
        } else {
            console.log('json 9.0.6');
            console.log('written by Trent Mick');
            console.log('https://github.com/trentm/json');
        }
        return;
    }

    var lookupStrs = opts.args;

    var execVm = Boolean(process.env.JSON_EXEC && process.env.JSON_EXEC === 'vm');
    var condFuncs = [];
    if (!execVm) {
        for (var i = 0; i < opts.condSnippets.length; i++) {
            condFuncs[i] = funcWithReturnFromSnippet(opts.condSnippets[i]);
        }
    }
    var condScripts = [];
    if (execVm) {
        for (var i = 0; i < opts.condSnippets.length; i++) {
            condScripts[i] = vm.createScript(opts.condSnippets[i]);
        }
    }
    var cond = Boolean(condFuncs.length + condScripts.length);

    var exeFuncs = [];
    if (!execVm) {
        for (var i = 0; i < opts.exeSnippets.length; i++) {
            exeFuncs[i] = new Function(opts.exeSnippets[i]);
        }
    }
    var exeScripts = [];
    if (execVm) {
        for (var i = 0; i < opts.exeSnippets.length; i++) {
            exeScripts[i] = vm.createScript(opts.exeSnippets[i]);
        }
    }
    var exe = Boolean(exeFuncs.length + exeScripts.length);

    var lookups = lookupStrs.map(function (lookup) {
        return parseLookup(lookup, opts.lookupDelim);
    });

    getInput(opts, function (err, buffer, filename) {
        if (err) {
            console.warn('json: error: %s', err.message);
            process.exit(1);
        }

        while (true) {
            if (buffer.slice(0, 5) === 'HTTP/') {
                var index = buffer.indexOf('\r\n\r\n');
                var sepLen = 4;
                if (index == -1) {
                    index = buffer.indexOf('\n\n');
                    sepLen = 2;
                }
                if (index != -1) {
                    if (!opts.dropHeaders) {
                        process.stdout.write(buffer.slice(0, index + sepLen));
                    }
                    var is100Continue = (buffer.slice(0, 21) === 'HTTP/1.1 100 Continue');
                    buffer = buffer.slice(index + sepLen);
                    if (is100Continue) {
                        continue;
                    }
                }
            }
            break;
        }

        var input = parseInput(buffer, null, opts.group, opts.merge);
        if (input.error) {
            if (!opts.quiet) {
                console.warn('json: error: input is not JSON: %s', input.error.message);
            }
            if (!opts.validate) {
                process.stdout.write(buffer);
                if (buffer.length && buffer[buffer.length - 1] !== '\n') {
                    process.stdout.write('\n');
                }
            }
            process.exit(1);
        }
        if (opts.validate) {
            process.exit(0);
        }

        var data = input.datum;

        if (opts.items) {
            if (!Array.isArray(data)) {
                var key;
                var array = [];
                for (key in data) {
                    if (data.hasOwnProperty(key)) {
                        array.push({ key: key, value: data[key] });
                    }
                }
                data = array;
            }
        }

        if (exe) {
            if (opts.array || (opts.array === null && Array.isArray(data))) {
                var arrayified = false;
                if (!Array.isArray(data)) {
                    arrayified = true;
                    data = [data];
                }
                for (var i = 0; i < data.length; i++) {
                    var datum = data[i];
                    for (var j = 0; j < exeFuncs.length; j++) {
                        exeFuncs[j].call(datum);
                    }
                    for (var j = 0; j < exeScripts.length; j++) {
                        exeScripts[j].runInNewContext(datum);
                    }
                }
                if (arrayified) {
                    data = data[0];
                }
            } else {
                for (var j = 0; j < exeFuncs.length; j++) {
                    exeFuncs[j].call(data);
                }
                for (var j = 0; j < exeScripts.length; j++) {
                    exeScripts[j].runInNewContext(data);
                }
            }
        }

        if (cond) {
            if (opts.array || (opts.array === null && Array.isArray(data))) {
                var arrayified = false;
                if (!Array.isArray(data)) {
                    arrayified = true;
                    data = [data];
                }
                var filtered = [];
                for (var i = 0; i < data.length; i++) {
                    var datum = data[i];
                    var datumCopy = objCopy(datum);
                    var keep = true;
                    for (var j = 0; j < condFuncs.length; j++) {
                        if (!condFuncs[j].call(datumCopy)) {
                            keep = false;
                            break;
                        }
                    }
                    if (keep) {
                        for (var j = 0; j < condScripts.length; j++) {
                            if (!condScripts[j].runInNewContext(datumCopy)) {
                                keep = false;
                                break;
                            }
                        }
                        if (keep) {
                            filtered.push(datum);
                        }
                    }
                }
                if (arrayified) {
                    data = (filtered.length ? filtered[0] : []);
                } else {
                    data = filtered;
                }
            } else {
                var keep = true;
                var dataCopy = objCopy(data);
                for (var j = 0; j < condFuncs.length; j++) {
                    if (!condFuncs[j].call(dataCopy)) {
                        keep = false;
                        break;
                    }
                }
                if (keep) {
                    for (var j = 0; j < condScripts.length; j++) {
                        if (!condScripts[j].runInNewContext(dataCopy)) {
                            keep = false;
                            break;
                        }
                    }
                }
                if (!keep) {
                    data = undefined;
                }
            }
        }

        var lookupsAreIndeces = false;
        if (lookups.length) {
            if (opts.array) {
                if (!Array.isArray(data)) data = [data];
                var table = [];
                for (var j = 0; j < data.length; j++) {
                    var datum = data[j];
                    var row = {};
                    for (var i = 0; i < lookups.length; i++) {
                        var lookup = lookups[i];
                        var value = lookupDatum(datum, lookup);
                        if (value !== undefined) {
                            row[lookup.join('.')] = value;
                        }
                    }
                    table.push(row);
                }
                data = table;
            } else {
                if (Array.isArray(data)) {
                    lookupsAreIndeces = true;
                    for (var i = 0; i < lookups.length; i++) {
                        if (lookups[i].length !== 1 || isNaN(Number(lookups[i]))) {
                            lookupsAreIndeces = false;
                            break;
                        }
                    }
                }
                var row = {};
                for (var i = 0; i < lookups.length; i++) {
                    var lookup = lookups[i];
                    var value = lookupDatum(data, lookup);
                    if (value !== undefined) {
                        row[lookup.join('.')] = value;
                    }
                }
                data = row;
            }
        }

        if (opts.outputKeys) {
            data = Object.keys(data);
        }

        var datasets = [];
        if (opts.outputMode === 2) {
            if (lookups.length === 1 && !opts.array) {
                data = data[lookups[0].join('.')];
            } else if (lookupsAreIndeces) {
                var flattened = [];
                for (var i = 0; i < lookups.length; i++) {
                    var lookupStr = lookups[i].join('.');
                    if (data.hasOwnProperty(lookupStr)) {
                        flattened.push(data[lookupStr]);
                    }
                }
                data = flattened;
            }
            datasets.push([data, '\n', false]);
        } else if (lookups.length) {
            if (opts.array) {
                for (var j = 0; j < data.length; j++) {
                    var row = data[j];
                    for (var i = 0; i < lookups.length - 1; i++) {
                        datasets.push([row[lookups[i].join('.')], opts.delim, true]);
                    }
                    datasets.push([row[lookups[i].join('.')], '\n', true]);
                }
            } else {
                for (var i = 0; i < lookups.length; i++) {
                    datasets.push([data[lookups[i].join('.')], '\n', false]);
                }
            }
        } else if (opts.array) {
            if (!Array.isArray(data)) data = [data];
            for (var j = 0; j < data.length; j++) {
                datasets.push([data[j], '\n', false]);
            }
        } else {
            datasets.push([data, '\n', false]);
        }

        var write = process.stdout.write.bind(process.stdout);
        for (var i = 0; i < datasets.length; i++) {
            var dataset = datasets[i];
            var output = null;
            switch (opts.outputMode) {
            case 3:
                output = util.inspect(dataset[0], false, Infinity, process.stdout.isTTY);
                break;
            case 2:
                if (typeof (dataset[0]) !== 'undefined') {
                    output = JSON.stringify(dataset[0], null, opts.jsonIndent);
                }
                break;
            case 4:
                if (dataset[0] === undefined) {
                } else if (Array.isArray(dataset[0])) {
                    var bits = ['[\n'];
                    dataset[0].forEach(function (d) {
                        bits.push('  ');
                        bits.push(JSON.stringify(d, null, 0).replace(/,"(?![,:])/, ', "'));
                        bits.push(',\n');
                    });
                    bits.push(bits.pop().slice(0, -2) + '\n');
                    bits.push(']');
                    output = bits.join('');
                } else {
                    output = JSON.stringify(dataset[0], null, 0);
                }
                break;
            case 1:
                if (typeof (dataset[0]) === 'string') {
                    output = dataset[0];
                } else if (typeof (dataset[0]) !== 'undefined') {
                    output = JSON.stringify(dataset[0], null, opts.jsonIndent);
                }
                break;
            default:
                throw new Error('unknown output mode: ' + opts.outputMode);
            }
            if (output && output.length) {
                if (opts.crlf) {
                    output = output.replace(/\n/g, "\r\n");
                }
                write(output);
                write(dataset[1]);
            } else if (dataset[2]) {
                write(dataset[1]);
            }
        }
    });
}

if (require.main === module) {
    main(process.argv);
}

